var e=class{static async saveTable(e,t,n){try{console.log(`[DataService] Saving table ${e} to ${t}`);let r={tableId:e,filename:t,rows:n.map(e=>e.toJSON?e.toJSON():e)};console.log(`[DataService] Payload: ${JSON.stringify(r).substring(0,200)}...`);let i=await fetch(`/api/save-table`,{method:`POST`,headers:{"Content-Type":`application/json`},body:JSON.stringify(r)});console.log(`[DataService] Response status: ${i.status}`),console.log(`[DataService] Response headers:`,i.headers);let a=i.headers.get(`content-type`),o=``;try{o=await i.text(),console.log(`[DataService] Raw response: ${o.substring(0,200)}`)}catch(e){console.error(`[DataService] Failed to read response`,e)}if(!i.ok)throw console.error(`[DataService] Error response: ${o}`),Error(`HTTP ${i.status}: ${o.substring(0,100)}`);if(!a||!a.includes(`application/json`))throw console.error(`[DataService] Non-JSON response: ${o.substring(0,100)}`),Error(`Server returned non-JSON response: ${o.substring(0,100)}`);let s=JSON.parse(o);return console.log(`[Save] ${s.message}`),s}catch(t){throw console.error(`[Save Error] Failed to save ${e}:`,t),t}}};export{e as DataService};